const tank = {
  litres: 10,
  fill(amount) {
    this.litres += amount;

    return this;
  },
  double() {
    this.litres *= 2;

    return this;
  },
  read() {
    return this.litres;
  },
};

console.log(tank.fill(5).double().read());
console.log(tank.double().fill(5).read());
console.log(tank.fill(tank.read()).read());
console.log(tank.double() === tank);
